messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Red vs Blue Race</title>
  <style>
    body { margin: 0; overflow: hidden; background: #000; }
    canvas { display: block; }
    .info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      font-family: 'Arial', sans-serif;
      font-size: 16px;
      background: rgba(0,0,0,0.5);
      padding: 8px 16px;
      border-radius: 8px;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div class="info">🏁 Red vs Blue — Overtake & Win</div>
  <script type="module">
    import * as THREE from './three.module.js';

    // --- Setup scene, camera, renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 6, 12);
    camera.lookAt(0, 0, 5);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0x404060);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    scene.add(dirLight);

    const fillLight = new THREE.DirectionalLight(0xffccaa, 0.6);
    fillLight.position.set(-5, 4, -5);
    scene.add(fillLight);

    // --- Ground ---
    const groundGeo = new THREE.PlaneGeometry(30, 40);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a7a4a, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.z = 10; // extend along z
    ground.receiveShadow = true;
    scene.add(ground);

    // --- Road / Track ---
    const roadGeo = new THREE.PlaneGeometry(4, 40);
    const roadMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.9 });
    const road = new THREE.Mesh(roadGeo, roadMat);
    road.rotation.x = -Math.PI / 2;
    road.position.z = 10;
    road.position.y = 0.01;
    road.receiveShadow = true;
    scene.add(road);

    // Lane markings (dashed)
    for (let z = -10; z < 30; z += 2) {
      const dashGeo = new THREE.PlaneGeometry(0.1, 1.2);
      const dashMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
      const dash = new THREE.Mesh(dashGeo, dashMat);
      dash.rotation.x = -Math.PI / 2;
      dash.position.set(0, 0.02, z);
      scene.add(dash);
    }

    // --- Finish line (checkered strip) ---
    const finishGeo = new THREE.PlaneGeometry(4, 1.5);
    const finishMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.5 });
    const finish = new THREE.Mesh(finishGeo, finishMat);
    finish.rotation.x = -Math.PI / 2;
    finish.position.set(0, 0.03, 20);
    scene.add(finish);

    // Checker squares on finish line
    for (let i = -2; i < 2; i++) {
      for (let j = -0.5; j < 0.6; j += 0.5) {
        const sqGeo = new THREE.PlaneGeometry(0.5, 0.5);
        const sqMat = new THREE.MeshStandardMaterial({ color: (i + j) % 2 === 0 ? 0xffffff : 0x000000 });
        const sq = new THREE.Mesh(sqGeo, sqMat);
        sq.rotation.x = -Math.PI / 2;
        sq.position.set(i * 0.5 + 0.25, 0.04, 20 + j * 0.5);
        scene.add(sq);
      }
    }

    // --- Start line (white strip) ---
    const startGeo = new THREE.PlaneGeometry(4, 0.3);
    const startMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const start = new THREE.Mesh(startGeo, startMat);
    start.rotation.x = -Math.PI / 2;
    start.position.set(0, 0.03, -5);
    scene.add(start);

    // --- Cars ---
    // Blue car (leads early)
    const blueCar = createCar(0x2255ff);
    blueCar.position.set(-1.0, 0.25, -5); // left lane
    scene.add(blueCar);

    // Red car (starts behind, accelerates)
    const redCar = createCar(0xff2222);
    redCar.position.set(1.0, 0.25, -5); // right lane
    scene.add(redCar);

    // Car creation helper: simple body + wheels + spoiler
    function createCar(color) {
      const carGroup = new THREE.Group();

      // Body
      const bodyGeo = new THREE.BoxGeometry(1.8, 0.6, 3.2);
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.4, metalness: 0.2 });
      const body = new THREE.Mesh(bodyGeo, bodyMat);
      body.position.y = 0.3;
      body.castShadow = true;
      carGroup.add(body);

      // Cabin / roof
      const cabinGeo = new THREE.BoxGeometry(1.2, 0.5, 1.6);
      const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6 });
      const cabin = new THREE.Mesh(cabinGeo, cabinMat);
      cabin.position.set(0, 0.7, -0.2);
      cabin.castShadow = true;
      carGroup.add(cabin);

      // Wheels (4)
      const wheelGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.2, 16);
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.9 });
      const wheelPositions = [
        [-0.9, 0.2, 1.0],
        [0.9, 0.2, 1.0],
        [-0.9, 0.2, -1.0],
        [0.9, 0.2, -1.0]
      ];
      wheelPositions.forEach(pos => {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        wheel.castShadow = true;
        carGroup.add(wheel);
      });

      // Spoiler
      const spoilerGeo = new THREE.BoxGeometry(1.4, 0.1, 0.4);
      const spoilerMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
      const spoiler = new THREE.Mesh(spoilerGeo, spoilerMat);
      spoiler.position.set(0, 0.8, -1.4);
      spoiler.castShadow = true;
      carGroup.add(spoiler);

      return carGroup;
    }

    // --- Race parameters ---
    const trackLength = 25; // from z=-5 to z=20
    const startZ = -5;
    const finishZ = 20;

    // Animation timing (seconds)
    let raceTime = 0;
    const raceDuration = 6; // seconds per race loop

    // Car progress (0 to 1)
    let blueProgress = 0;
    let redProgress = 0;

    // --- Animation loop ---
    function animate() {
      requestAnimationFrame(animate);

      const delta = 1 / 60; // assume 60fps
      raceTime += delta;

      // Loop race
      if (raceTime > raceDuration) {
        raceTime = 0;
        blueProgress = 0;
        redProgress = 0;
      }

      // Progress curves:
      // Blue: fast start, then slows down (leads early)
      // Red: slow start, then accelerates (overtakes mid, wins)
      const t = raceTime / raceDuration;

      // Blue: linear-ish with early lead: 0.6*t^0.6 + 0.4*t
      // Actually want blue to lead early: use easeOut for blue (fast early, slow late)
      // Blue: 0.9*t + 0.1*t^2? That gives early lead but still reaches 1 at end.
      // Let's make blue: 0.95*t + 0.05*t^2 -> early lead, but red catches.
      // Red: 0.1*t + 0.9*t^2 -> slow start, fast late.
      // At t=0.5: blue ~0.5, red ~0.275 -> blue leads.
      // At t=0.7: blue ~0.7, red ~0.5 -> red still behind.
      // At t=0.85: blue ~0.85, red ~0.75 -> red catching.
      // At t=1: both 1.0 (red wins by crossing first? Actually red should cross first)
      // To make red win, red must reach 1 slightly before blue.
      // Let's set blue: t (linear) but red: 0.15*t + 0.85*t^2? At t=1 both 1.
      // To have red win, red should finish first: at t=1, both at finish, but red crosses slightly earlier.
      // We can make red: 0.1*t + 0.9*t^2, and blue: 0.95*t + 0.05*t^2.
      // At t=0.9: blue=0.95*0.9+0.05*0.81=0.855+0.0405=0.8955
      // red=0.1*0.9+0.9*0.81=0.09+0.729=0.819 -> red still behind.
      // At t=1: both 1.0. But we need red to cross first. 
      // Instead, make red reach 1 at t=0.95, and blue reach 1 at t=1.0.
      // So red: progress = min(1, (t/0.95))? But then blue: t.
      // Let's use piecewise:
      // Blue: t (linear) -> reaches 1 at t=1.
      // Red: 0.15*t + 0.85*t^2, but scale so that red reaches 1 at t=0.95.
      // Actually easier: red = (t/0.95) clamped, but that's linear.
      // Let's use: red = 0.1*t + 0.9*t^2, then normalize by dividing by max at t=1? 
      // We want red to finish first: red crosses at t=0.95, blue at t=1.
      // So red progress = t/0.95 (clamped to 1). That's linear, but we want slow start.
      // Use: red = (t^2) * 1.05? At t=1 -> 1.05 >1, so clamp. 
      // Let's do: red = 0.25*t + 0.75*t^2. At t=1 -> 1.0. But to finish earlier, 
      // we can have red = 0.25*t + 0.75*t^2, and then multiply by 1.05? 
      // Simpler: use two segments: 
      // For t<0.95: red = (0.25/0.95)*t + (0.75/0.95)*t^2? That's complex.
      // Let's just make red faster in second half:
      // red = t < 0.5 ? 0.4*t : 0.4*t + (t-0.5)*1.2? 
      // I'll use: 
      // blueProgress = t (linear)
      // redProgress = 0.15*t + 0.85*t^2 (slow start, fast finish)
      // At t=1, red=1.0, blue=1.0. Red crosses at same time? Actually red overtakes mid-race and wins.
      // To have red win, red must cross first. Since both finish at t=1, we can make red finish at t=0.98.
      // So redProgress = min(1, 0.15*t + 0.85*t^2) * 1.02? At t=1 -> 1.02 -> clamp to 1.
      // At t=0.95: red = 0.15*0.95+0.85*0.9025 = 0.1425+0.767125=0.909625 -> *1.02=0.9278
      // blue at t=0.95: 0.95. red still behind.
      // At t=1: red=1, blue=1. Same.
      // To make red win, let red reach 1 at t=0.98, blue at t=1.0.
      // So red = min(1, (0.15*t + 0.85*t^2) * 1.02) -> at t=0.98: 0.15*0.98+0.85*0.9604=0.147+0.81634=0.96334 *1.02=0.9826 -> still <1.
      // At t=1: 1.02 -> clamp to 1. So red crosses at t=1.0 too.
      // Let's just make red: t^2 * 1.1? At t=1 ->1.1 clamp. At t=0.95 ->0.9025*1.1=0.99275, blue=0.95 -> red ahead!
      // At t=0.95 red already at 0.993, blue at 0.95 -> red overtook and wins.
      // So red: min(1, 1.1 * t * t) ; blue: t (linear)
      // At t=0.5: red=1.1*0.25=0.275, blue=0.5 -> blue leads.
      // At t=0.7: red=1.1*0.49=0.539, blue=0.7 -> blue leads.
      // At t=0.85: red=1.1*0.7225=0.79475, blue=0.85 -> blue still slightly ahead.
      // At t=0.9: red=1.1*0.81=0.891, blue=0.9 -> red slightly behind.
      // At t=0.93: red=1.1*0.8649=0.9514, blue=0.93 -> red ahead! 
      // At t=0.95: red=1.1*0.9025=0.99275, blue=0.95 -> red clearly ahead.
      // At t=1: red=1.1 clamp to 1, blue=1.0. Red wins (crossed earlier).
      // Great! Use red = min(1, 1.1 * t * t), blue = t.
      // This gives blue early lead, red overtakes around t=0.93 and wins.

      const blueT = t; // linear
      const redT = Math.min(1, 1.1 * t * t); // quadratic, faster late

      // Convert progress to Z position: startZ + progress * (finishZ - startZ)
      const blueZ = startZ + blueT * (finishZ - startZ);
      const redZ = startZ + redT * (finishZ - startZ);

      // Update car positions
      blueCar.position.z = blueZ;
      redCar.position.z = redZ;

      // Slight bounce for wheels (visual)
      // Keep cars at y=0.25

      // Camera: keep both cars in view
      // Position camera behind and above, looking at midpoint between cars
      const midZ = (blueZ + redZ) / 2;
      const midX = 0; // both cars around x=-1 and 1
      camera.position.set(0, 5 + 0.2 * Math.sin(raceTime * 2), midZ + 8);
      camera.lookAt(0, 0.5, midZ + 2);

      renderer.render(scene, camera);
    }

    animate();

    // --- Resize handler ---
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```
